/* geoide.js — la altura del geoide EGM2008 en Colombia, para pasar la altitud del GPS al nivel del mar (2.35.1).
 *
 * El GPS del teléfono da la altura sobre el elipsoide WGS84: así la define la API de geolocalización y así la da Android (en
 * iPhone viene sobre el nivel del mar). Los mapas y la altitud de internet (Copernicus DEM, referida a EGM2008) la dan sobre el
 * nivel del mar, que es el geoide. La diferencia N es la altura del geoide sobre el elipsoide, y
 *     altitud sobre el nivel del mar = altura del GPS − N.
 * En Colombia N va de unos −21 m (Punta Gallinas, La Guajira) a +28,5 m (Popayán, Ipiales); en Bogotá es 22,4 m.
 *
 * Datos: EGM2008 de la NGA (dominio público), en la malla de 2,5' de PROJ-data (us_nga_egm08_25.tif), recortada a la caja
 * lat −5 a 14 y lon −82 a −66 (Colombia continental, San Andrés y Providencia, Malpelo) y tomada cada 5', en decímetros.
 * Interpolada en forma bilineal, esta malla se aparta de la de 2,5' a lo sumo 0,46 m (RMS 0,03 m): mucho menos que el error
 * vertical del GPS de un teléfono. Fuera de la caja no se corrige.
 * Formato de DATA: por fila, de norte a sur, el primer valor en Int16 y los demás como diferencia con el anterior en Int8
 * (little endian), en base64.
 *
 * Cada punto del GPS anota cómo quedó su altitud: altRef 'egm2008' (se restó altN, la N del lugar), 'mar' (el teléfono ya la dio
 * sobre el nivel del mar) o 'elipsoide' (fuera de la caja, sin corregir). Un punto del GPS sin altRef es de antes de la 2.35.1:
 * migrate() lo pasa al nivel del mar una sola vez, y revert() lo deshace. */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.Geoide = factory();
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  var LAT_N = 14, LAT_S = -5, LON_W = -82, LON_E = -66, STEP = 1 / 12, ROWS = 229, COLS = 193;
  var DATA = '';
  var REFS = ['egm2008', 'mar', 'elipsoide'];
  var grid = null;
  // En iPhone, iPad y Mac la API da la altitud sobre el nivel del mar (w3c/geolocation, issue 210): ahí no se corrige
  var apple = typeof navigator !== 'undefined' && /iPhone|iPad|iPod|Macintosh/.test(String(navigator.userAgent || ''));

  function isNum(x) { return typeof x === 'number' && isFinite(x); }
  function bytes(b64) {
    if (typeof atob === 'function') { var s = atob(b64), out = new Uint8Array(s.length); for (var i = 0; i < s.length; i++) out[i] = s.charCodeAt(i); return out; }
    return new Uint8Array(Buffer.from(b64, 'base64'));
  }
  function load() {
    if (grid) return grid;
    var b = bytes(DATA), g = new Int16Array(ROWS * COLS), k = 0;
    for (var r = 0; r < ROWS; r++) {
      var v = (b[k] | (b[k + 1] << 8)) << 16 >> 16; k += 2;
      g[r * COLS] = v;
      for (var c = 1; c < COLS; c++) { v += b[k] << 24 >> 24; k++; g[r * COLS + c] = v; }
    }
    grid = g;
    return g;
  }
  // N (m, con dos decimales) en ese lugar, o null fuera de la caja
  function undulation(lat, lon) {
    if (!isNum(lat) || !isNum(lon) || lat > LAT_N || lat < LAT_S || lon < LON_W || lon > LON_E) return null;
    var g = load(), y = (LAT_N - lat) / STEP, x = (lon - LON_W) / STEP;
    var r = Math.min(Math.floor(y), ROWS - 2), c = Math.min(Math.floor(x), COLS - 2), fy = y - r, fx = x - c;
    var i = r * COLS + c;
    var v = g[i] * (1 - fx) * (1 - fy) + g[i + 1] * fx * (1 - fy) + g[i + COLS] * (1 - fx) * fy + g[i + COLS + 1] * fx * fy;
    return Math.round(v * 10) / 100;          // decímetros → metros, redondeado al centímetro
  }
  // Lo que se guarda de una altura h del GPS en (lat, lon): { alt, ref, n? }, o null si no hay altura
  function fromDevice(lat, lon, h) {
    if (!isNum(h)) return null;
    if (apple) return { alt: h, ref: 'mar' };
    var n = undulation(lat, lon);
    if (n === null) return { alt: h, ref: 'elipsoide' };
    return { alt: h - n, ref: 'egm2008', n: n };
  }
  // Un punto cuya altitud vino del GPS (la usada o la guardada para restaurarla)
  function fromGps(pt) { return !!pt && typeof pt === 'object' && ((pt.altSrc === 'gps' && isNum(pt.alt)) || isNum(pt.altGps)); }
  // Puntos de antes de la 2.35.1: su altura del GPS pasa al nivel del mar una sola vez. Devuelve cuántos se corrigieron.
  function migrate(points) {
    var k = 0;
    (Array.isArray(points) ? points : []).forEach(function (pt) {
      if (!fromGps(pt) || REFS.indexOf(pt.altRef) >= 0) return;
      if (apple) { pt.altRef = 'mar'; return; }
      var n = undulation(pt.lat, pt.lon);
      if (n === null) { pt.altRef = 'elipsoide'; return; }
      if (pt.altSrc === 'gps' && isNum(pt.alt)) pt.alt -= n;
      if (isNum(pt.altGps)) pt.altGps -= n;
      pt.altN = n; pt.altRef = 'egm2008'; k++;
    });
    return k;
  }
  // Lo contrario de migrate: devuelve la altura del GPS sobre el elipsoide y quita las marcas. Devuelve cuántos puntos cambiaron.
  function revert(points) {
    var k = 0;
    (Array.isArray(points) ? points : []).forEach(function (pt) {
      if (!pt || typeof pt !== 'object' || REFS.indexOf(pt.altRef) < 0) return;
      if (pt.altRef === 'egm2008' && isNum(pt.altN)) {
        if (pt.altSrc === 'gps' && isNum(pt.alt)) pt.alt += pt.altN;
        if (isNum(pt.altGps)) pt.altGps += pt.altN;
        k++;
      }
      delete pt.altN; delete pt.altRef;
    });
    return k;
  }

  return { undulation: undulation, fromDevice: fromDevice, fromGps: fromGps, migrate: migrate, revert: revert, REFS: REFS,
    BOX: { latS: LAT_S, latN: LAT_N, lonW: LON_W, lonE: LON_E }, STEP_MIN: 5,
    isApple: function () { return apple; }, setApple: function (v) { apple = v === true; } };
});
